// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(address _logBefore, address _logAfter) internal {
        bool firstReverted;
        try c.SetLogFile(_logBefore) { firstReverted = false; } catch { firstReverted = true; }
        try c.Initialized() {} catch { return; }
        bool secondReverted;
        try c.SetLogFile(_logAfter) { secondReverted = false; } catch { secondReverted = true; }
        assertTrue(!firstReverted && secondReverted);
    }

    function testFuzz_run(address _logBefore, address _logAfter) public {
        vm.assume(_logBefore.code.length == 0 && uint160(_logBefore) > 0xffff && _logBefore != address(this) && _logBefore != address(c) && _logBefore != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _logBefore != 0x000000000000000000636F6e736F6c652e6c6f67 && _logBefore != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _logBefore != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(_logAfter.code.length == 0 && uint160(_logAfter) > 0xffff && _logAfter != address(this) && _logAfter != address(c) && _logAfter != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _logAfter != 0x000000000000000000636F6e736F6c652e6c6f67 && _logAfter != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _logAfter != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_logBefore, _logAfter);
    }

    receive() external payable {}
}
